import { spreadsheetValue } from "./safety.ts";

// RFC 4180: quote cells containing a delimiter, quote or line break; double embedded quotes.
function quoteCell(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

export function csvRecord(values: string[]): string {
  const cells = values.map(value => quoteCell(spreadsheetValue(value)));
  // Serialize one record.
  return cells.join(",") + "\r\n";
}
EOF
cat >> tests/export.test.ts <<'EOF'
test("quotes cells containing delimiters, quotes and line breaks",()=>{
  assert.equal(exportContacts([{id:"c3",name:"Jane Doe",company:"Acme, Inc",email:"jane@example.test"}]),"id,name,company,email\r\nc3,Jane Doe,\"Acme, Inc\",jane@example.test\r\n");
  assert.equal(exportContacts([{id:"c4",name:"Jane Doe",company:"The \"Best\" Co\r\nLtd",email:""}]),"id,name,company,email\r\nc4,Jane Doe,\"The \"\"Best\"\" Co\r\nLtd\",\r\n");
  assert.equal(exportContacts([{id:"c5",name:"Jane Doe",company:"=SUM(A1,A2)",email:""}]),"id,name,company,email\r\nc5,Jane Doe,\"'=SUM(A1,A2)\",\r\n");
});
EOF
